    .footer-col-title {
      font-size: 0.7rem; font-weight: 700;
      letter-spacing: 0.08em; text-transform: uppercase;
      color: var(--dark); margin-bottom: 12px;
    }
    .footer-links { list-style: none; display: flex; flex-direction: column; gap: 7px; }
    .footer-links a {
      font-size: 0.8125rem; color: var(--text-muted);
      transition: color 0.12s;
    }
    .footer-links a:hover { color: var(--dark); }
    .footer-bottom {
      display: flex; align-items: center; justify-content: space-between;
      flex-wrap: wrap; gap: 12px;
      padding-top: 24px; border-top: 1px solid var(--border);
      font-size: 0.78rem; color: var(--text-muted);
    }
    .footer-status {
      display: flex; align-items: center; gap: 6px;
    }
    .status-dot {
      width: 7px; height: 7px; border-radius: 50%;
      background: #22c55e;
    }

    /* ── RESPONSIVE ── */
    @media (max-width: 1024px) {
      .featured-grid { grid-template-columns: 1fr 1fr; }
      .featured-card-primary { grid-row: auto; }
      .posts-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
      .cta-section { grid-template-columns: 1fr; }
    }
    @media (max-width: 768px) {
      .featured-grid { grid-template-columns: 1fr; }
      .posts-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, 1fr); }
      .nav-links > .nav-item:not(:first-child):not(:last-child) { display: none; }
      .dropdown-mega { grid-template-columns: 1fr 1fr; width: 360px; }
      .stats-strip { grid-template-columns: 1fr; }
      .blog-header { padding-top: 28px; }
    }
    @media (max-width: 480px) {
      .footer-grid { grid-template-columns: 1fr; }
      .nav-link { padding: 8px 8px; font-size: 0.8125rem; }
      .cta-card { padding: 28px 24px; }
    }

    /* hidden util */
    .hidden { display: none !important; }
  </style>
</head>
